INSERT INTO evaluation_criteria (code, number, name, standard_id, description, complexity, is_mandatory, status, service_id) VALUES
('TSTH-001', 001, '1. El talento humano en salud y otros profesionales que se relacionan con la atención o resultados en salud de los usuarios, cuentan con los titulos, según aplique, de educación superior o certificados de aptitud ocupacional, expedidos por la entidad educ', (SELECT id FROM evaluation_standards WHERE code = SUBSTRING('TSTH-001', 1, POSITION('-' IN 'TSTH-001') - 1) LIMIT 1), 'Talento Humano', 'complex', true, 'active', (SELECT id FROM services LIMIT 1)),
('TSTH-002', 002, '2. El talento humano en salud cuenta con copia de la resolución de autorización del ejercicio expedido por la autoridad competente  o inscripción e en el ReTHUS', (SELECT id FROM evaluation_standards WHERE code = SUBSTRING('TSTH-002', 1, POSITION('-' IN 'TSTH-002') - 1) LIMIT 1), 'Talento Humano', 'medium', true, 'active', (SELECT id FROM services LIMIT 1)),
('TSTH-003', 003, '3. El prestador de servicios de salud determina la cantidad necesaria de talento humano requerido para cada uno de los servicios ofertados y prestados, de acuerdo con la capacidad instalada, la relación entre la oferta y demanda, la oportunidad en la pres', (SELECT id FROM evaluation_standards WHERE code = SUBSTRING('TSTH-003', 1, POSITION('-' IN 'TSTH-003') - 1) LIMIT 1), 'Talento Humano', 'complex', true, 'active', (SELECT id FROM services LIMIT 1)),
('TSTH-004', 004, '4. El prestador de servicios de salud que actúe como escenario de práctica formativa en el área de la salud, cuenta con:', (SELECT id FROM evaluation_standards WHERE code = SUBSTRING('TSTH-004', 1, POSITION('-' IN 'TSTH-004') - 1) LIMIT 1), 'Talento Humano', 'simple', true, 'active', (SELECT id FROM services LIMIT 1)),
('TSTH-005', 005, '4.1. Convenio vigente con la institución educativa autorizada por la entidad competente', (SELECT id FROM evaluation_standards WHERE code = SUBSTRING('TSTH-005', 1, POSITION('-' IN 'TSTH-005') - 1) LIMIT 1), 'Talento Humano', 'simple', true, 'active', (SELECT id FROM services LIMIT 1)),
('TSTH-006', 006, '4.2. Información documentada de los mecanismos de supervisión permanente del personal en entrnamiento', (SELECT id FROM evaluation_standards WHERE code = SUBSTRING('TSTH-006', 1, POSITION('-' IN 'TSTH-006') - 1) LIMIT 1), 'Talento Humano', 'simple', true, 'active', (SELECT id FROM services LIMIT 1)),
('TSTH-007', 007, '4.3. Estudio de la capacidad instalada en el cual se dtermine el número máximo de estudiantes que simultaneamente puedan acceder por programa de formación y por jornada, para cada uno de los servicios que se utilicen como escenarios de práctica formativa ', (SELECT id FROM evaluation_standards WHERE code = SUBSTRING('TSTH-007', 1, POSITION('-' IN 'TSTH-007') - 1) LIMIT 1), 'Talento Humano', 'complex', true, 'active', (SELECT id FROM services LIMIT 1)),
('TSTH-008', 008, '5. En los servicios de salud diferentes a los servicios de consulta externa especializada de dolor y cuidado paliativo, donde se atienden pacientes con enfermedades terminales, crónicas, degenerativas e irreversibles, a los cuales se les decida como condu', (SELECT id FROM evaluation_standards WHERE code = SUBSTRING('TSTH-008', 1, POSITION('-' IN 'TSTH-008') - 1) LIMIT 1), 'Talento Humano', 'complex', true, 'active', (SELECT id FROM services LIMIT 1)),
('TSTH-009', 009, '6. El talento humano en salud de los servicios de atención del parto, cuidado intensivo y cuidado intermedio neonatal, pediátrico y adultos, cuentan con constancia de asistencia en las acciones de formación continua para la gestión del duelo', (SELECT id FROM evaluation_standards WHERE code = SUBSTRING('TSTH-009', 1, POSITION('-' IN 'TSTH-009') - 1) LIMIT 1), 'Talento Humano', 'medium', true, 'active', (SELECT id FROM services LIMIT 1)),
('TSTH-010', 010, '7. En los servicios de salud donde se realicen imagenes diagnósticas por ultrasonido, cuenta con médico especialista en radiologia e imagenes diagnósticas también podrán realizar imagenes diagnósticas aquellos médicos especialistas, quienes en su pensum o', (SELECT id FROM evaluation_standards WHERE code = SUBSTRING('TSTH-010', 1, POSITION('-' IN 'TSTH-010') - 1) LIMIT 1), 'Talento Humano', 'complex', true, 'active', (SELECT id FROM services LIMIT 1)),
('TSTH-011', 011, '8. Los profesionales de la medicina de los servicios de hospitalización de baja, mediana y alta complejidad, hospitalización paciente crónico con y sin ventilador, cuidados intensivos neonatales, pediátricos y adultos; urgencias, y servicios del grupo qui', (SELECT id FROM evaluation_standards WHERE code = SUBSTRING('TSTH-011', 1, POSITION('-' IN 'TSTH-011') - 1) LIMIT 1), 'Talento Humano', 'complex', true, 'active', (SELECT id FROM services LIMIT 1)),
('TSTH-012', 012, '9. Las instituciones prestadoras de servicios de salud con servicios de cuidado intensivo pediatrico y adulto que adicionalmente habiliten servicio quirurgico de neurocirugía, tienen disponibilidad de coordinador operativo de trasplantes.', (SELECT id FROM evaluation_standards WHERE code = SUBSTRING('TSTH-012', 1, POSITION('-' IN 'TSTH-012') - 1) LIMIT 1), 'Talento Humano', 'medium', true, 'active', (SELECT id FROM services LIMIT 1)),
('TSTH-013', 013, '10. El talento humano en salud de los servicios de salud de los grupos de consulta externa, internación y el servicio de urgencias, cuentan con constancia de asistencia en las acciones de formación continua en la atención integral en salud de las personas', (SELECT id FROM evaluation_standards WHERE code = SUBSTRING('TSTH-013', 1, POSITION('-' IN 'TSTH-013') - 1) LIMIT 1), 'Talento Humano', 'medium', true, 'active', (SELECT id FROM services LIMIT 1)),
('TSTH-014', 014, '11. El talento humano en salud de los servicios de transporte asistencial, atención prehospitalaria y urgencias, cuentasn con constancia de asistencia en las acciones de formación continua en la atención a personas víctimas de ataques con agentes químicos', (SELECT id FROM evaluation_standards WHERE code = SUBSTRING('TSTH-014', 1, POSITION('-' IN 'TSTH-014') - 1) LIMIT 1), 'Talento Humano', 'medium', true, 'active', (SELECT id FROM services LIMIT 1)),
('TSTH-015', 015, '12. Cuando en un servicio de salud se realicen "pruebas en punto de atención del paciente - (point of care testing - POCT)", el talento humano en salud qeu las realice, a excepción del profesional en bacteriologia cuenta con constancia de asistencia en la', (SELECT id FROM evaluation_standards WHERE code = SUBSTRING('TSTH-015', 1, POSITION('-' IN 'TSTH-015') - 1) LIMIT 1), 'Talento Humano', 'complex', true, 'active', (SELECT id FROM services LIMIT 1)),
('TSTH-016', 016, '13. Procedimientos bajo sedación:', (SELECT id FROM evaluation_standards WHERE code = SUBSTRING('TSTH-016', 1, POSITION('-' IN 'TSTH-016') - 1) LIMIT 1), 'Talento Humano', 'simple', true, 'active', (SELECT id FROM services LIMIT 1)),
('TSTH-017', 017, '13.1 Cuando fuera de salas de cirugía, se realicen procedimientos bajo sedación Grado I y II, adicional al profesional de salud que realiza el procedimiento, cuenta con:', (SELECT id FROM evaluation_standards WHERE code = SUBSTRING('TSTH-017', 1, POSITION('-' IN 'TSTH-017') - 1) LIMIT 1), 'Talento Humano', 'medium', true, 'active', (SELECT id FROM services LIMIT 1)),
('TSTH-018', 018, '13.1.1. Profesional en la medicina especialista en anestesiologia, o profesional de la medicina o profesional en odontologia, según aplique, el cual será el encargado de administrar el medicamento y realizar el monitoreo continuo del paciente (registro de', (SELECT id FROM evaluation_standards WHERE code = SUBSTRING('TSTH-018', 1, POSITION('-' IN 'TSTH-018') - 1) LIMIT 1), 'Talento Humano', 'complex', true, 'active', (SELECT id FROM services LIMIT 1)),
('TSTH-019', 019, '13.1.2. Todos los profesionales, a excepción del profesional de la medicina especialista en anestesiologia, deben demostrar constancia de asistencia a curso de formación continua en soporte vital básico y sedación', (SELECT id FROM evaluation_standards WHERE code = SUBSTRING('TSTH-019', 1, POSITION('-' IN 'TSTH-019') - 1) LIMIT 1), 'Talento Humano', 'complex', true, 'active', (SELECT id FROM services LIMIT 1)),
('TSTH-020', 020, '13.1.3 Para sedacción con óxido nitroso en odontologia, el profesional de la odontología cuenta con constancia de asistencia en las acciones de formación continua para uso clínico y práctico de este gas.', (SELECT id FROM evaluation_standards WHERE code = SUBSTRING('TSTH-020', 1, POSITION('-' IN 'TSTH-020') - 1) LIMIT 1), 'Talento Humano', 'medium', true, 'active', (SELECT id FROM services LIMIT 1)),
('TSTH-021', 021, '13.2. Cuando fuera de las salas de cirugia, se realicen procedimientos bajo sedación grado III, adicional al profesional de salud que realiza el procedimiento, cuenta con profesional de la medicina con especialidad médico - quirúrgica, quién será el respo', (SELECT id FROM evaluation_standards WHERE code = SUBSTRING('TSTH-021', 1, POSITION('-' IN 'TSTH-021') - 1) LIMIT 1), 'Talento Humano', 'complex', true, 'active', (SELECT id FROM services LIMIT 1)),
('TSTH-022', 022, '13.3. Cuando fuera de las salas de cirugía, se realicen procedimientos bajo sedación grado IV, adicional al profesional de  salud que realiza el procedimiento, cuenta con profesional de la medicina especialisa en anestesiologia, quién será el responsable ', (SELECT id FROM evaluation_standards WHERE code = SUBSTRING('TSTH-022', 1, POSITION('-' IN 'TSTH-022') - 1) LIMIT 1), 'Talento Humano', 'complex', true, 'active', (SELECT id FROM services LIMIT 1)),
('TSTH-023', 023, '13.4 Cuenta con profesional de la medicina especialista en anestesiologia cuando la atención de trate de pacientes con caracteristicas particulares: poco colaboradores; edades extremas; con enfermedades severas:cardíacas, pulmonares, hepáticas, renales o ', (SELECT id FROM evaluation_standards WHERE code = SUBSTRING('TSTH-023', 1, POSITION('-' IN 'TSTH-023') - 1) LIMIT 1), 'Talento Humano', 'complex', true, 'active', (SELECT id FROM services LIMIT 1)),
('TSTH-024', 024, 'Modalidad de telemedicina prestador remisor - prestador de referencia', (SELECT id FROM evaluation_standards WHERE code = SUBSTRING('TSTH-024', 1, POSITION('-' IN 'TSTH-024') - 1) LIMIT 1), 'Talento Humano', 'simple', true, 'active', (SELECT id FROM services LIMIT 1)),
('TSTH-025', 025, '14. Adicional a los criterios del estándar de talento humano enunciados que le aplique, el talento humano en salud que preste directamente un servicio de salud bajo la modalidad telemedicina cuentan con constancia de asistencia en las acciones de formació', (SELECT id FROM evaluation_standards WHERE code = SUBSTRING('TSTH-025', 1, POSITION('-' IN 'TSTH-025') - 1) LIMIT 1), 'Talento Humano', 'complex', true, 'active', (SELECT id FROM services LIMIT 1)),
('TSINF-001', 001, 'Edificaciones de uso exclusivo en salud', (SELECT id FROM evaluation_standards WHERE code = SUBSTRING('TSINF-001', 1, POSITION('-' IN 'TSINF-001') - 1) LIMIT 1), 'Información', 'simple', true, 'active', (SELECT id FROM services LIMIT 1)),
('TSINF-002', 002, '1. Los servicios de salud de urgencias, de atención del parto, hospitalarios y de cirugía que realicen procedimientos quirúrgicos no ambulatorios, solo se pueden prestar en edificaciones de uso exclusivo de salud.', (SELECT id FROM evaluation_standards WHERE code = SUBSTRING('TSINF-002', 1, POSITION('-' IN 'TSINF-002') - 1) LIMIT 1), 'Información', 'medium', true, 'active', (SELECT id FROM services LIMIT 1)),
('TSINF-003', 003, '2. Los servicios de salud de: urgencias, cirugía y del grupo de internación, así como en los servicios de salud donde se realice el proceso de esterilización, deben contar con ambiente de aseo de uso exclusivo', (SELECT id FROM evaluation_standards WHERE code = SUBSTRING('TSINF-003', 1, POSITION('-' IN 'TSINF-003') - 1) LIMIT 1), 'Información', 'medium', true, 'active', (SELECT id FROM services LIMIT 1)),
