('TSINF-013', 013, '7. En edificaciones de uso mixto pueden funsionar los prestadores de servicios de salud que oferten y presten servicios de los grupos de consulta externa. de apoyo diagnóstico y complementación terapeutica y los servicios del grupo quirurgico que realicen', (SELECT id FROM evaluation_standards WHERE code = SUBSTRING('TSINF-013', 1, POSITION('-' IN 'TSINF-013') - 1) LIMIT 1), 'Información', 'complex', true, 'active', (SELECT id FROM services LIMIT 1)),
